From 39ba90cd290a482212b22dbf1450b5bee4b5f13e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:59:32 +0100
Subject: [PATCH] kcm, kded: add an option to lock the screen when a device
 disconnects

There was no way to lock the screen automatically when walking away
with a paired phone or watch. The device page now has a switch for it,
and the daemon locks the screen when that device goes out of range.

BUG: 266829
---
 src/kcm/ui/Device.qml                     | 22 ++++++++++++++
 src/kded/devicemonitor.cpp                | 35 +++++++++++++++++++++++
 src/kded/devicemonitor.h                  |  2 ++
 src/settings/bluedevilglobalsettings.kcfg |  3 ++
 4 files changed, 62 insertions(+)

diff --git a/src/kcm/ui/Device.qml b/src/kcm/ui/Device.qml
index 85814855..5f4d0b37 100644
--- a/src/kcm/ui/Device.qml
+++ b/src/kcm/ui/Device.qml
@@ -17,6 +17,7 @@ import org.kde.kcmutils as KCMUtils

 import org.kde.bluezqt as BluezQt
 import org.kde.bluedevil.components as BluedevilComponents
+import org.kde.bluedevil.kcm

 import "script.js" as Script

@@ -198,6 +199,27 @@ KCMUtils.SimpleKCM {
                 }
             }

+            RowLayout {
+                spacing: Kirigami.Units.smallSpacing
+
+                QQC2.Switch {
+                    text: i18n("Lock screen when disconnected")
+                    checked: GlobalSettings.lockScreenDevices.includes(root.device.address)
+                    onToggled: {
+                        const devices = GlobalSettings.lockScreenDevices.filter(address => address !== root.device.address);
+                        if (checked) {
+                            devices.push(root.device.address);
+                        }
+                        GlobalSettings.lockScreenDevices = devices;
+                        GlobalSettings.save();
+                    }
+                }
+
+                Kirigami.ContextualHelpButton {
+                    toolTipText: i18n("When enabled, the screen will be locked when this device disconnects, for example when you take it out of range.")
+                }
+            }
+
             QQC2.Button {
                 icon.name: "document-share-symbolic"
                 text: i18n("Send File")
diff --git a/src/kded/devicemonitor.cpp b/src/kded/devicemonitor.cpp
index 1de54443..4400c39e 100644
--- a/src/kded/devicemonitor.cpp
+++ b/src/kded/devicemonitor.cpp
@@ -10,6 +10,8 @@
 #include "bluedevildaemon.h"
 #include "bluedevilglobalsettings.h"

+#include <QDBusConnection>
+#include <QDBusMessage>
 #include <QTimer>

 #include <KConfigGroup>
@@ -139,6 +141,10 @@ void DeviceMonitor::deviceConnectedChanged(bool connected)

     BluezQt::DevicePtr device = static_cast<BluezQt::Device *>(sender())->toSharedPtr();
     updateDevicePlace(device);
+
+    if (!connected) {
+        lockScreenIfNeeded(device);
+    }
 }

 void DeviceMonitor::login1PrepareForSleep(bool active)
@@ -147,6 +153,8 @@ void DeviceMonitor::login1PrepareForSleep(bool active)
         return;
     }

+    m_preparingForSleep = active;
+
     if (active) {
         qCDebug(BLUEDEVIL_KDED_LOG) << "About to suspend";
         saveState();
@@ -259,4 +267,31 @@ void DeviceMonitor::updateDevicePlace(BluezQt::DevicePtr device)
     }
 }

+void DeviceMonitor::lockScreenIfNeeded(BluezQt::DevicePtr device)
+{
+    if (m_preparingForSleep) {
+        return;
+    }
+
+    GlobalSettings::self()->load();
+    if (!GlobalSettings::lockScreenDevices().contains(device->address())) {
+        return;
+    }
+
+    // Turning Bluetooth off also disconnects every device, so wait for the adapter
+    // state to settle and only lock when the device itself went away
+    QTimer::singleShot(2000, this, [this, device]() {
+        if (device->isConnected() || !device->adapter() || !device->adapter()->isPowered() || !m_manager->isBluetoothOperational()) {
+            return;
+        }
+
+        qCDebug(BLUEDEVIL_KDED_LOG) << "Locking the screen because" << device->address() << "disconnected";
+        QDBusMessage message = QDBusMessage::createMethodCall(QStringLiteral("org.freedesktop.ScreenSaver"),
+                                                              QStringLiteral("/ScreenSaver"),
+                                                              QStringLiteral("org.freedesktop.ScreenSaver"),
+                                                              QStringLiteral("Lock"));
+        QDBusConnection::sessionBus().asyncCall(message);
+    });
+}
+
 #include "moc_devicemonitor.cpp"
diff --git a/src/kded/devicemonitor.h b/src/kded/devicemonitor.h
index 039e8a8c..b7b862d8 100644
--- a/src/kded/devicemonitor.h
+++ b/src/kded/devicemonitor.h
@@ -42,10 +42,12 @@ private:

     void clearPlaces();
     void updateDevicePlace(BluezQt::DevicePtr device);
+    void lockScreenIfNeeded(BluezQt::DevicePtr device);

     KFilePlacesModel *places();

     BluezQt::Manager *m_manager;
     bool m_isParentValid;
+    bool m_preparingForSleep = false;
     KFilePlacesModel *m_places = nullptr;
 };
diff --git a/src/settings/bluedevilglobalsettings.kcfg b/src/settings/bluedevilglobalsettings.kcfg
index d89d9811..c7d01409 100644
--- a/src/settings/bluedevilglobalsettings.kcfg
+++ b/src/settings/bluedevilglobalsettings.kcfg
@@ -24,5 +24,8 @@ xsi:schemaLocation="http://www.kde.org/standards/kcfg/1.0
         <entry name="connectedDevices" type="StringList">
             <default>QStringList()</default>
         </entry>
+        <entry name="lockScreenDevices" type="StringList">
+            <label>Devices that lock the screen when they disconnect</label>
+        </entry>
     </group>
 </kcfg>
